/* CSS */
.bintang {
  background-color: yellow;
  width: 50px;
  height: 50px;
  /* 1. Tambahkan pemanggilan animation di sini */
  animation: kelap-kelip 1s infinite;
}

@keyframes kelap-kelip {
  0% { opacity: 1; }
  /* 2. Tambahkan tahapan 50% di bawah ini */
  50% { opacity: 0.1; }
  100% { opacity: 1; }
}
